// =====================================================
//  تطعيس  |  TATEES — Dune Bashing
//  A = بنزين | gas     B = فرامل وريوس | brake / reverse
//  ⬅️ ➡️ = لف | steer
//  انتبه لعداد الميلان! لو صار أحمر، السيارة بتنقلب
//  Watch the tilt gauges! In the red, you will roll over
// =====================================================

// ---------- إعدادات الطعوس | Dune settings ----------
let MAP = 256              // حجم الخريطة | map size (cells)
let CELL = 10              // حجم كل خانة | size of one cell
let DUNE_HEIGHT = 118       // ارتفاع الطعوس | how tall the dunes are
let DUNE_SPACING = 64      // المسافة بين الطعوس | distance between dunes (cells)

// ---------- إعدادات السيارة | Car settings ----------
let ENGINE = 75            // قوة الماكينة | engine power
let MAX_SPEED = 340        // أعلى سرعة | top speed
let GRAVITY = 98           // الجاذبية | gravity
let SAND_DRAG = 0.55       // الرمل يبطّئك | soft sand slows you
let TURN_RATE = 1.5        // سرعة اللف | steering speed
let SAND_GRIP = 0.7        // مسكة الكفرات في الرمل | tyre grip on sand
let SAFE_TILT = 20         // ميلان آمن | safe tilt (degrees)
let DANGER_TILT = 30       // ميلان خطر | danger tilt
let ROLL_LIMIT = 38        // هنا تنقلب | you roll over here
let LAND_LIMIT = 34        // نزلة غلط من القفزة | bad landing angle

// ---------- الخريطة | Height map ----------
let heights = Buffer.create(MAP * MAP)
let colors = Buffer.create(MAP * MAP)

function duneHeight (cx: number, cy: number): number {
    let a = cx * 2 * Math.PI / MAP
    let b = cy * 2 * Math.PI / MAP
    // الطعس: طلعة طويلة هادية وسلّة قصيرة حادة | a dune: long gentle windward side, short steep slip face
    let shift = 6 * Math.sin(b * 2) + 4 * Math.sin(b * 5 + 1)
    let phase = ((cx + shift) % DUNE_SPACING + DUNE_SPACING) % DUNE_SPACING / DUNE_SPACING
    // الطلعة 68% والسلّة 32% (زاوية السلّة حوالي 32 درجة مثل الطعوس الحقيقية)
    // windward side 68%, slip face 32% (about 32 degrees, like real dunes)
    let profile = 0
    if (phase < 0.68) {
        profile = phase / 0.68
    } else {
        profile = (1 - phase) / 0.32
    }
    // نعدّل القمة والقاع شوي | round the crest and the foot a little
    if (profile < 0.08) {
        profile = profile * profile / 0.16
    } else if (profile > 0.92) {
        profile = 1 - (1 - profile) * (1 - profile) / 0.16
    }
    let size = 0.65 + 0.35 * Math.sin(b * 3 + Math.cos(a * 2))
    let rolling = 8 * (Math.sin(a * 3 + b * 2) + 0.7 * Math.cos(b * 4 - a))
    return 40 + DUNE_HEIGHT * size * profile + rolling
}

function buildDunes () {
    for (let y = 0; y < MAP; y++) {
        for (let x = 0; x < MAP; x++) {
            heights[y * MAP + x] = Math.max(0, Math.min(255, Math.round(duneHeight(x, y))))
        }
    }
    // لون كل خانة حسب الشمس | colour each cell by the sunlight
    for (let y = 0; y < MAP; y++) {
        for (let x = 0; x < MAP; x++) {
            let dx = cellH(x + 1, y) - cellH(x - 1, y)
            let dy = cellH(x, y + 1) - cellH(x, y - 1)
            let light = 0 - dx * 0.9 - dy * 0.4
            let c = 4
            if (light > 4) {
                c = 3
            } else if (light < -9) {
                c = 6
            } else if (light < -2.5) {
                c = 5
            }
            // خط القمة يلمع | the crest line shines
            let here = cellH(x, y)
            if (here > cellH(x - 2, y) + 1 && here > cellH(x + 2, y) + 1 && here > 90) {
                c = 9
            }
            colors[y * MAP + x] = c
        }
    }
}
function cellH (x: number, y: number): number {
    return heights[((y % MAP + MAP) % MAP) * MAP + (x % MAP + MAP) % MAP]
}
// ارتفاع ناعم لأي نقطة | smooth height at any point
function groundAt (wx: number, wy: number): number {
    let fx = wx / CELL
    let fy = wy / CELL
    let x0 = Math.floor(fx)
    let y0 = Math.floor(fy)
    let tx = fx - x0
    let ty = fy - y0
    let h00 = cellH(x0, y0)
    let h10 = cellH(x0 + 1, y0)
    let h01 = cellH(x0, y0 + 1)
    let h11 = cellH(x0 + 1, y0 + 1)
    return (h00 * (1 - tx) + h10 * tx) * (1 - ty) + (h01 * (1 - tx) + h11 * tx) * ty
}

